import type { Branch } from "../lib/ink";
import Tree from "./Tree.astro";

interface Props {
  id: string;
  mark: string;
  title: string;
  lede?: string;
  tree?: Branch;
  place?: "br" | "tl";
  class?: string;
}

const { id, mark, title, lede, tree, place, class: extra = "" } = Astro.props;
---

<section class={`chapter ${extra}`} id={id}>
  {tree && <Tree branch={tree} place={place} />}
  <p class="mark">{mark}</p>
  <h2>{title}</h2>
  {lede && <p class="line">{lede}</p>}
  <slot />
</section>
---
import type { Branch } from "../lib/ink";

interface Props {
  branch: Branch;
  /** which corner it grows from */
  place?: "br" | "tl";
  class?: string;
}

const { branch, place = "br", class: extra = "" } = Astro.props;
---

<svg class={`tree tree--${place} ${extra}`} viewBox="0 0 1000 1000" aria-hidden="true">
  {branch.strokes.map((st) => <path d={st.d} stroke-width={st.w} pathLength="1" />)}
  {
    branch.buds.map((b, i) => (
      <circle cx={b.x} cy={b.y} r={b.r} style={`--f:${8 + i * 1.4}%;--t:${40 + i * 1.4}%`} />
    ))
  }
</svg>
---
interface Props {
  items: [string, string][];
}
const { items } = Astro.props;
---

<ul class="craft">
  {
    items.map(([term, note]) => (
      <li>
        <h3>{term}</h3>
        <p>{note}</p>
      </li>
    ))
  }
</ul>
