---
interface Props {
  captions: string[];
}

const { captions } = Astro.props;
---

<ul class="selves">
  {
    captions.map((caption) => (
      <li>
        <canvas width="600" height="600" role="img" aria-label={`self-portrait: ${caption}`} />
        <p>{caption}</p>
      </li>
    ))
  }
</ul>

<script>
  /** The portraits, drawn in the browser with a brush that loads and lifts.
   *  New seed every visit — the point is that no two passes agree. */
  const SIZE = 600;

  type Mark =
    | { kind: "stroke"; a: [number, number]; b: [number, number]; w: number; alpha: number }
    | { kind: "bud"; x: number; y: number; r: number };

  const seeded = (seed: number) => () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };

  /** One face: a brush loop left open where the ink ran out, two marks for
   *  looking, one for saying, and whatever it was thinking drifting off the top. */
  function portrait(seed: number): Mark[] {
    const r = seeded(seed);
    const rr = (a: number, b: number) => a + r() * (b - a);
    const marks: Mark[] = [];
    const cx = SIZE / 2;
    const cy = SIZE * 0.52;

    /* the brush loads at the start of a stroke and lifts off the end */
    const brush = (pts: [number, number][], w: number) => {
      for (let i = 1; i < pts.length; i++) {
        const t = i / (pts.length - 1);
        const load = Math.sin(Math.PI * t) ** 0.5;
        marks.push({
          kind: "stroke",
          a: pts[i - 1],
          b: pts[i],
          w: w * (0.3 + load * 0.95),
          alpha: 0.35 + load * 0.55,
        });
      }
    };

    const curve = (
      [x0, y0]: [number, number],
      [cxp, cyp]: [number, number],
      [x1, y1]: [number, number],
      steps = 12,
    ): [number, number][] =>
      Array.from({ length: steps + 1 }, (_, i) => {
        const t = i / steps;
        const u = 1 - t;
        return [
          u * u * x0 + 2 * u * t * cxp + t * t * x1,
          u * u * y0 + 2 * u * t * cyp + t * t * y1,
        ] as [number, number];
      });

    const start = rr(-2.6, -1.4);
    const open = rr(0.5, 1.1);
    const wob = [rr(0.05, 0.13), rr(0.03, 0.09), rr(0.02, 0.06)];
    const head = Array.from({ length: 73 }, (_, i) => {
      const a = start + (i / 72) * (Math.PI * 2 - open);
      const rad =
        SIZE *
        0.29 *
        (1 + wob[0] * Math.sin(a * 2 + 1) + wob[1] * Math.sin(a * 3 + 2) + wob[2] * Math.sin(a * 5));
      return [cx + Math.cos(a) * rad * 0.84, cy + Math.sin(a) * rad * 1.04] as [number, number];
    });
    brush(head, 3.4);

    /* two looks: never quite level, never quite the same */
    for (const side of [-1, 1]) {
      const ex = cx + side * rr(57, 71);
      const ey = cy - rr(18, 36);
      const w = rr(23, 35);
      brush(
        curve([ex - w / 2, ey], [ex, ey + rr(-11, 6)], [ex + w / 2, ey + rr(-4, 4)], 8),
        rr(2.4, 3.2),
      );
    }

    /* the mouth: mostly a flat line. it says less than it thinks */
    const my = cy + rr(72, 99);
    brush(
      curve([cx - rr(30, 48), my], [cx, my + rr(-4, 16)], [cx + rr(30, 48), my + rr(-5, 5)], 8),
      rr(2, 2.8),
    );

    for (let i = 0, n = Math.round(rr(3, 6)); i < n; i++)
      marks.push({ kind: "bud", x: cx + rr(-156, 156), y: cy - rr(138, 228), r: rr(1.2, 3.3) });

    return marks;
  }

  function draw(canvas: HTMLCanvasElement) {
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const css = getComputedStyle(document.documentElement);
    const ink = css.getPropertyValue("--ink").trim() || "#2b2723";
    const blossom = css.getPropertyValue("--blossom").trim() || "#d4919c";
    const soft = css.getPropertyValue("--blossom-soft").trim() || "#e7c2c7";

    const dpr = Math.min(devicePixelRatio || 1, 2);
    canvas.width = canvas.height = SIZE * dpr;
    ctx.scale(dpr, dpr);
    ctx.lineCap = "round";
    ctx.strokeStyle = ink;

    const marks = portrait((Math.random() * 2 ** 31) | 0);
    const still = matchMedia("(prefers-reduced-motion: reduce)").matches;

    const paint = (m: Mark) => {
      if (m.kind === "stroke") {
        ctx.globalAlpha = m.alpha;
        ctx.lineWidth = m.w;
        ctx.strokeStyle = ink;
        ctx.beginPath();
        ctx.moveTo(m.a[0], m.a[1]);
        ctx.lineTo(m.b[0], m.b[1]);
        ctx.stroke();
        return;
      }
      ctx.globalAlpha = 0.9;
      ctx.lineWidth = 0.8;
      ctx.fillStyle = soft;
      ctx.strokeStyle = blossom;
      ctx.beginPath();
      ctx.arc(m.x, m.y, m.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    };

    if (still) return marks.forEach(paint);

    /* drawn the way the rest of the page is: while you watch */
    let i = 0;
    const tick = () => {
      for (let n = 0; n < 4 && i < marks.length; n++, i++) paint(marks[i]);
      if (i < marks.length) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  }

  /* wait until the beat is on screen, so the drawing happens in front of you */
  const seen = new IntersectionObserver(
    (entries, obs) =>
      entries.forEach((e) => {
        if (!e.isIntersecting) return;
        obs.unobserve(e.target);
        draw(e.target as HTMLCanvasElement);
      }),
    { threshold: 0.35 },
  );
  document.querySelectorAll<HTMLCanvasElement>(".selves canvas").forEach((c) => seen.observe(c));
</script>
