      [cx + hw * (far > 0 ? 0.94 : 1.0) + turn * 10 + jit(4), eyeY + hh * 0.12],
      [cx + hw * 0.66 + turn * 16 + jit(4), eyeY + hh * 0.62],
      [cx + turn * 26 + jit(3), chinY],
      [cx - hw * 0.66 + turn * 16 + jit(4), eyeY + hh * 0.62],
      [cx - hw * (far > 0 ? 1.0 : 0.94) + turn * 10 + jit(4), eyeY + hh * 0.12],
      [cx - hw * (far > 0 ? 0.97 : 0.9) + turn * 8 + jit(4), eyeY - hh * 0.44],
      [cx - hw * 0.56 + jit(4), crownY + hh * 0.16],
