        [
          [sx + jit(10), crownY + rr(10, 40)],
          [sx - far * rr(6, 22), eyeY - hh * rr(0.1, 0.3)],
          [sx - far * rr(2, 26), eyeY + hh * rr(0.1, 0.5)],
        ],
        rr(2.5, 6),
        rr(0.3, 0.6),
        [0.2, 0.42],
        0.45,
