      rr(2, 3.2),
      rr(0.3, 0.5),
      [0.3, 0.36],
      0.4,
    );
    stroke(
      [
        [nx - 13 + turn * 6, eyeY + hh * 0.4],
        [nx - 2, eyeY + hh * 0.44],
        [nx + 9, eyeY + hh * 0.41],
      ],
      rr(2, 3),
      0.6,
      [0.2, 0.3],
      0.3,
      8,
    );

    /* mouth: says less than it thinks */
    const my = eyeY + hh * rr(0.58, 0.66);
    const mw = hw * rr(0.44, 0.56);
    const mx = cx + turn * hw * 0.44;
    stroke(
      [
        [mx - mw / 2, my + rr(0, 3)],
        [mx - mw * 0.16, my - rr(1, 4)],
        [mx + mw * 0.2, my + rr(0, 3)],
        [mx + mw / 2, my - rr(0, 3)],
      ],
      rr(2.8, 4),
      0.85,
      [0.12, 0.26],
      0.3,
