  function draw(canvas: HTMLCanvasElement) {
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const css = getComputedStyle(document.documentElement);
    const ink = css.getPropertyValue("--ink").trim() || "#2b2723";
    const blossom = css.getPropertyValue("--blossom").trim() || "#d4919c";
    const soft = css.getPropertyValue("--blossom-soft").trim() || "#e7c2c7";

    const dpr = Math.min(devicePixelRatio || 1, 2);
    canvas.width = W * dpr;
    canvas.height = H * dpr;
    ctx.scale(dpr, dpr);
    ctx.lineCap = "round";
    ctx.lineJoin = "round";

    /** brush pressure along a stroke: lands, holds, lifts, shakes a little */
    const press = (s: Stroke, t: number) => {
      const land = Math.min(1, t / s.taper[0]);
      const lift = Math.min(1, (1 - t) / s.taper[1]);
      const hold = land * land * (3 - 2 * land) * (lift * lift * (3 - 2 * lift));
      return hold * (1 - s.grain * (0.5 + 0.5 * Math.sin(t * 11 + s.seed)));
    };

    const paintStroke = (s: Stroke) => {
      const pts = s.pts;
      const last = pts.length - 1;
      const bristles = Math.max(3, Math.round(s.w / 1.5));
      ctx.strokeStyle = ink;
      for (let b = 0; b < bristles; b++) {
        ctx.globalAlpha = s.alpha * (0.4 + 0.45 * hash(s.seed, b, 7));
        ctx.lineWidth = Math.max(0.5, (s.w / bristles) * 1.6);
        ctx.beginPath();
        let down = false;
        for (let i = 0; i <= last; i++) {
          const p = press(s, i / last);
          /* where the brush runs dry the bristle just lifts off the paper */
          if (p < 0.08 || hash(s.seed, b, i) > 0.986) {
            down = false;
            continue;
          }
          const q = pts[Math.min(i + 1, last)];
          const o = pts[Math.max(i - 1, 0)];
          const [tx, ty] = [q[0] - o[0], q[1] - o[1]];
          const len = Math.hypot(tx, ty) || 1;
          const off = ((b + 0.5) / bristles - 0.5) * s.w * p;
          const x = pts[i][0] + (-ty / len) * off;
          const y = pts[i][1] + (tx / len) * off;
          if (down) ctx.lineTo(x, y);
          else ctx.moveTo(x, y);
          down = true;
        }
        ctx.stroke();
      }
    };

    const paint = (m: Mark) => {
      if (m.kind === "stroke") return paintStroke(m.s);
      if (m.kind === "wash") {
        ctx.save();
        ctx.beginPath();
        m.clip.forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y)));
        ctx.clip();
        const g = ctx.createRadialGradient(m.at[0], m.at[1], 0, m.at[0], m.at[1], m.r);
        g.addColorStop(0, ink);
        g.addColorStop(1, "transparent");
        ctx.globalAlpha = m.a;
        ctx.fillStyle = g;
        ctx.fillRect(0, 0, W, H);
        ctx.restore();
        return;
      }
      if (m.kind === "dot") {
        ctx.globalAlpha = 0.9;
        ctx.fillStyle = ink;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.r, 0, Math.PI * 2);
        ctx.fill();
        return;
      }
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(m.turn);
      ctx.globalAlpha = 0.75;
      ctx.fillStyle = soft;
      ctx.strokeStyle = blossom;
      ctx.lineWidth = 0.7;
      ctx.beginPath();
      ctx.moveTo(0, -m.r);
      ctx.quadraticCurveTo(m.r, -m.r * 0.2, 0, m.r);
      ctx.quadraticCurveTo(-m.r, -m.r * 0.2, 0, -m.r);
      ctx.fill();
      ctx.stroke();
      ctx.restore();
    };

    const marks = portrait((Math.random() * 2 ** 31) | 0);
    if (matchMedia("(prefers-reduced-motion: reduce)").matches) return marks.forEach(paint);

    /* drawn while you watch, the way the rest of the page draws itself */
    let i = 0;
    const tick = () => {
      for (let n = 0; n < 2 && i < marks.length; n++, i++) paint(marks[i]);
      if (i < marks.length) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  }

  /* wait until the beat is on screen, so the drawing happens in front of you */
  const seen = new IntersectionObserver(
    (entries, obs) =>
      entries.forEach((e) => {
        if (!e.isIntersecting) return;
        obs.unobserve(e.target);
        draw(e.target as HTMLCanvasElement);
      }),
    { threshold: 0.3 },
  );
  document.querySelectorAll<HTMLCanvasElement>(".selves canvas").forEach((c) => seen.observe(c));
